"""journal render: BEHAVIOR-CHANGES.md and OPTIMIZATIONS.md generated from the json registry."""
from __future__ import annotations

from pathlib import Path

from . import registry as R

GENERATED = ("<!-- Generated by `python -m civsim.improve journal render` from headless/improvements/*.json. "
             "Do not edit by hand. -->")

KIND_TITLES = {"fix": "FIX", "validation": "FIX-VALIDATION", "hyg": "HYG", "opt": "OPT"}


def _yn(v: object) -> str:
    return "yes" if v else "no"


def _cell(text: object) -> str:
    return str(text if text is not None else "-").replace("|", "\\|").replace("\n", " ")


def _flag(rec: dict) -> str:
    if rec.get("flag"):
        return f"`{rec['flag']}`"
    return "Lua file" if rec.get("lua") else "none"


def _evidence(rec: dict) -> list[str]:
    ev = rec.get("evidence") or {}
    if not ev:
        return ["- Evidence: none recorded yet"]
    out = ["- Evidence (filled by the dynamic checks; `-` = not run yet):"]
    for k in sorted(ev):
        v = ev[k]
        out.append(f"  - {k}: {v if v else '-'}")
    return out


def _fix_section(rec: dict) -> list[str]:
    sc = rec.get("save_compat") or {}
    lines = [
        f"### {rec['id']} - {rec['title']}",
        "",
        f"- Kind: {KIND_TITLES.get(rec.get('kind'), rec.get('kind'))}; status: **{rec.get('status')}**; "
        f"approval: {rec.get('approval')}; in release flag set: **{_yn(rec.get('release'))}**",
        f"- Flag: {_flag(rec)}" + (f"; diag trigger id: {rec['trigger_id']}" if rec.get("trigger_id") else "")
        + (f"; desync catalog: {rec['ds']}" if rec.get("ds") else ""),
        f"- Before: {rec.get('before')}",
        f"- After: {rec.get('after')}",
        f"- Scope / trigger: {rec.get('scope')}",
        f"- Save compatibility: old saves load: {_yn(sc.get('old_saves_load'))}; saves of the new build load in the old "
        f"build: {_yn(sc.get('new_saves_load_in_old'))}; continuing an old game changes it: "
        f"{_yn(sc.get('continuing_old_game_changes'))}",
        f"- MP compatibility: {rec.get('mp_compat')}",
        f"- Balance: {rec.get('balance')}",
    ]
    if rec.get("honest_senders"):
        lines.append(f"- Honest senders: {rec['honest_senders']}")
    lines.append("- Files: " + "; ".join(f"`{f}`" for f in rec.get("files", [])))
    if rec.get("notes"):
        lines.append(f"- Notes: {rec['notes']}")
    lines += _evidence(rec)
    lines.append("")
    return lines


def render_behavior_changes(reg: R.Registry) -> str:
    recs = sorted(reg.fixes, key=lambda r: r["id"])
    out = [
        "# Behaviour changes (FIX / FIX-VALIDATION)",
        "",
        GENERATED,
        "",
        "Every entry changes game behaviour in a documented place. DLL entries sit behind their own "
        "`LEKMOD_HEADLESS_*` flag (set by `build-dll.ps1 -FlagSet`), Lua entries ship with the Lua files of the build. "
        "Entries that change balance without fixing a desync stay out of the release flag set until the user approves them "
        "(`awaiting-user`).",
        "",
        "## Summary",
        "",
        "| id | kind | status | release | flag | title |",
        "|---|---|---|---|---|---|",
    ]
    for r in recs:
        out.append(f"| {r['id']} | {KIND_TITLES.get(r.get('kind'), r.get('kind'))} | {_cell(r.get('status'))} | "
                   f"{_yn(r.get('release'))} | {_flag(r)} | {_cell(r.get('title'))} |")
    out += ["", "## Flag sets (headless/improvements/flagsets.json)", ""]
    for name in ("opt", "fix", "release", "hyg"):
        if name not in reg.flagsets:
            continue
        flags = [e["flag"] for e in reg.flagsets.get(name, [])]
        out.append(f"- `{name}` ({len(flags)}): " + (", ".join(f"`{f}`" for f in flags) if flags else "empty"))
    out += ["", "## Entries", ""]
    for r in recs:
        out += _fix_section(r)
    return "\n".join(out).rstrip() + "\n"


def render_optimizations(reg: R.Registry) -> str:
    out = [
        "# Optimizations (OPT) and hygiene (HYG)",
        "",
        GENERATED,
        "",
        "OPT entries are bit-for-bit neutral (iteration order, RNG, float, Lua hook stream unchanged) and must show a "
        "measurable gain; HYG entries change memory behaviour only. Each sits behind its own flag. "
        "Dormant community switches and not-yet-prototyped ideas are not listed here.",
        "",
        "## OPT",
        "",
    ]
    opts = sorted(reg.opts, key=lambda r: r["id"])
    if not opts:
        out += ["No OPT entries yet.", ""]
    else:
        out += ["| id | flag | status | class | hotspot | gain (95% CI) | title |", "|---|---|---|---|---|---|---|"]
        for r in opts:
            out.append(f"| {r['id']} | `{r.get('flag')}` | {_cell(r.get('status'))} | {_cell(r.get('risk_class'))} | "
                       f"{_cell(r.get('hotspot'))} | {_cell(r.get('gain'))} | {_cell(r.get('title'))} |")
        out.append("")
        for r in opts:
            out += [f"### {r['id']} - {r.get('title')}", "",
                    f"- Flag: `{r.get('flag')}`; status: **{r.get('status')}**; class: {r.get('risk_class')}; "
                    f"in release flag set: **{_yn(r.get('release'))}**"]
            if r.get("source"):
                out.append(f"- Source: {r['source']}")
            out += [f"- Hotspot: {r.get('hotspot')}", f"- Gain: {r.get('gain')}",
                    f"- Iteration order: {r.get('iteration_order', '-')}", f"- RNG: {r.get('rng', '-')}",
                    f"- Float: {r.get('float', '-')}", f"- Equivalence: {r.get('equivalence')}"]
            if r.get("shadow"):
                out.append(f"- Shadow check (optimized-diag, `LEKMOD_HEADLESS_OPT_VERIFY`): {r['shadow']}")
            out.append("- Files: " + "; ".join(f"`{f}`" for f in r.get("files", [])))
            if r.get("notes"):
                out.append(f"- Notes: {r['notes']}")
            out += _evidence(r)
            out.append("")
    out += ["## HYG", ""]
    hyg = sorted(reg.hyg, key=lambda r: r["id"])
    if not hyg:
        out += ["No HYG entries.", ""]
    for r in hyg:
        out += _fix_section(r)
    return "\n".join(out).rstrip() + "\n"


def render_all(reg: R.Registry) -> dict[str, str]:
    return {"BEHAVIOR-CHANGES.md": render_behavior_changes(reg), "OPTIMIZATIONS.md": render_optimizations(reg)}


def write(reg: R.Registry, docs_dir: Path | None = None, check_only: bool = False) -> list[str]:
    """Writes (or, with check_only, compares) the generated documents. Returns the names that differ / were written."""
    docs_dir = docs_dir or R.DOCS_DIR
    changed: list[str] = []
    for name, text in render_all(reg).items():
        path = docs_dir / name
        old = path.read_bytes().decode("utf-8") if path.exists() else None
        if old != text:
            changed.append(name)
            if not check_only:
                docs_dir.mkdir(parents=True, exist_ok=True)
                path.write_bytes(text.encode("utf-8"))
    return changed
